(17685, 'GEOG', '305', 'Fluvial Geomorphology', 'Emphasis on concepts related to fluvial processes, river mechanics, the relationship between environmental change and river regime. Selected topics include fluvial processes and landscape formation, flow and sediment regimes, channel processes, form and behaviour, river response to natural and anthropogenic change, and river management.', 0.50, NULL),
(17686, 'ECON', '248W', 'Economics of Health (WLU)', NULL, 0.50, NULL),
(17688, 'MUSIC', '416', 'Music Ensemble', 'The study of selected music literature through rehearsals and performance in one of the Department of Music ensembles: Chamber Choir, Chapel Choir, University Choir, Vocal Techniques, Orchestra, Instrumental Chamber Ensembles, Jazz Ensemble, World Music Ensemble. Regular attendance at rehearsals and performances is required.', 0.50, NULL),
(17689, 'ANTH', '100W', 'Cultures Today (WLU)', NULL, 0.50, NULL),
